WITH ranked AS (SELECT seller_id, gmv_proxy, RANK() OVER (ORDER BY gmv_proxy DESC) AS gmv_rank, SUM(gmv_proxy) OVER () AS total_gmv, SUM(gmv_proxy) OVER (ORDER BY gmv_proxy DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_gmv FROM marts.mart_seller_lifetime), scored AS (SELECT *, running_gmv/NULLIF(total_gmv,0) AS cumulative_share, NTILE(5) OVER (ORDER BY gmv_proxy DESC) AS quintile FROM ranked) SELECT quintile, COUNT(*) AS sellers, SUM(gmv_proxy) AS gmv_proxy, SUM(gmv_proxy)/MAX(total_gmv) AS share_of_gmv, MAX(cumulative_share) AS cumulative_share FROM scored GROUP BY quintile ORDER BY quintile;

